const ELEMENT_PROP_KEYS = new Set(["theme","question","answer","stagger","answerAt","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  question: "Why make the video?",
  answer: "Just make the video.",
  stagger: 3,
  answerAt: 40,
  fontFamily: "Barlow Condensed",
  scale: 1,
  delay: 0,
  speed: 1,
};

type HookUncurlElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof HookUncurlBase>;

const HookUncurlInner = forwardRef<
  HTMLDivElement,
  HookUncurlElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<HookUncurl>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <HookUncurlBase
          {...(componentProps as unknown as ComponentProps<typeof HookUncurlBase>)}
        />
      </div>
    </Sequence>
  );
});

export const HookUncurl = Interactive.withSchema({
  Component: HookUncurlInner,
  componentName: "<HookUncurl>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
